function validate([n, rounds]) {
  if (!Number.isInteger(n) || n < 2 || n > 100) return 'n is a whole number from 2 to 100.';
  if (!Array.isArray(rounds) || rounds.length < 2 || rounds.length > 101) return 'rounds needs 2 to 101 entries (m from 1 to 100).';
  if (rounds.some(v => !Number.isInteger(v) || v < 1 || v > n)) return 'Each entry of rounds is a sector from 1 to n.';
  for (let i = 0; i + 1 < rounds.length; i++) if (rounds[i] === rounds[i + 1]) return 'Neighbouring entries of rounds must differ.';
  return null;
}

