function mostVisited(n, rounds) {
  const start = rounds[0];
  const end = rounds[rounds.length - 1];
  const result = [];

  if (start <= end) {
    for (let sector = start; sector <= end; sector++) {
      result.push(sector);
    }
  } else {
    for (let sector = 1; sector <= end; sector++) {
      result.push(sector);
    }
    for (let sector = start; sector <= n; sector++) {
      result.push(sector);
    }
  }
  return result;
}

