function mostVisited(n, rounds) {
  // Walk the whole marathon one sector at a time and count visits.
  const visits = new Array(n + 1).fill(0);
  let at = rounds[0];
  visits[at]++;
  for (let i = 1; i < rounds.length; i++) {
    while (at !== rounds[i]) {
      at = at === n ? 1 : at + 1;
      visits[at]++;
    }
  }
  const most = Math.max(...visits);
  const out = [];
  for (let k = 1; k <= n; k++) if (visits[k] === most) out.push(k);
  return out;
}

