function generate(rand, size) {
  const n = size === 'large' ? 50 + Math.floor(rand() * 51) : 2 + Math.floor(rand() * 7);
  const m = size === 'large' ? 50 + Math.floor(rand() * 51) : 1 + Math.floor(rand() * 8);
  const rounds = [1 + Math.floor(rand() * n)];
  for (let i = 0; i < m; i++) {
    // Step forward 1 to n - 1 sectors so consecutive entries differ.
    const step = 1 + Math.floor(rand() * (n - 1));
    rounds.push(((rounds[i] - 1 + step) % n) + 1);
  }
  return [n, rounds];
}
